def net_tax(gross: int) -> int:
    # Calculate taxable income after standard deduction
    taxable_income = max(0, gross - 12000)

    # Calculate tax using marginal rates
    if taxable_income <= 10000:
        tax = taxable_income * 0.10
    elif taxable_income <= 40000:
        tax = 10000 * 0.10 + (taxable_income - 10000) * 0.22
    else:
        tax = 10000 * 0.10 + 30000 * 0.22 + (taxable_income - 40000) * 0.32

    # Calculate tax credit with phase-out above $50,000
    base_credit = 1000
    if taxable_income > 50000:
        credit_reduction = (taxable_income - 50000) * 0.05
        credit = max(0, base_credit - credit_reduction)
    else:
        credit = base_credit

    # Calculate final tax and convert to cents
    final_tax = max(0, tax - credit)
    return int(round(final_tax * 100))

